// Simulated Database (Slow)
const db = { 
  getTopUsers: async () => new Promise(res => setTimeout(() => res(['Alice', 'Bob']), 2000)) 
};

// Simulated Cache Memory (Fast)
let memoryCache = { data: null, timestamp: 0 };
const CACHE_LIFETIME = 10000; // 10 seconds

async function getTopUsers() {
  const now = Date.now();

  // 1. Check if cache exists AND is not expired
  if (memoryCache.data && (now - memoryCache.timestamp < CACHE_LIFETIME)) {
    console.log("⚡ CACHE HIT! Returning instantly.");
    return memoryCache.data;
  }

  // 2. CACHE MISS! Do the heavy lifting.
  console.log("🐌 CACHE MISS! Querying slow database...");
  const freshData = await db.getTopUsers();

  // 3. Save to cache for the next user!
  memoryCache = {
    data: freshData,
    timestamp: now
  };

  return freshData;
}

async function runDemo() {
  await getTopUsers(); // Miss (Takes 2 seconds)
  await getTopUsers(); // Hit (Instant)
}
runDemo();
